#include <bits/stdc++.h>
using namespace std;using I=long long;using G=vector<int>;using P=array<I,7>;
void need(bool q,string s){if(!q)throw runtime_error(s);}
void valid(G a){int n=a.size();for(int i=0;i<n;i++){need(a[i]>=0&&a[i]<(1<<n)&&!(a[i]>>i&1),"row");for(int j=0;j<i;j++)need(((a[i]>>j&1)+(a[j]>>i&1))==1,"pair");}}
P count(G a,int root=0){valid(a);int n=a.size(),N=1<<n,F=N-1;vector<I>en(N*n),st(N*n),H(N);H[0]=1;for(int i=0;i<n;i++)en[(1<<i)*n+i]=st[(1<<i)*n+i]=1;for(int S=1;S<N;S++)for(int v=0;v<n;v++)if(S>>v&1){int A=S^(1<<v);for(int w=0;w<n;w++)if(A>>w&1){if(a[w]>>v&1)en[S*n+v]+=en[A*n+w];else st[S*n+v]+=st[A*n+w];}H[S]+=en[S*n+v];}I L=0,R=0,b=0;for(int S=0;S<N;S++){L+=en[S*n+root]*H[F^S];R+=st[S*n+root]*H[F^S];}int D=F^(1<<root),A=D;while(true){b+=H[A]*H[D^A];if(!A)break;A=(A-1)&D;}return {H[F],st[F*n+root],en[F*n+root],L,R,H[D],b};}
G relabel(G a,int root){vector<int>ord{root};for(int i=0;i<(int)a.size();i++)if(i!=root)ord.push_back(i);G b(a.size());for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)a.size();j++)if(a[ord[i]]>>ord[j]&1)b[i]|=1<<j;return b;}
G move(G a,char op){int n=a.size();for(auto&x:a)x|=1<<n;a.push_back(0);if(op!='O'){a[0]^=1<<n;a[n]=1;}if(op=='J')a=relabel(a,n);return a;}
P trans(P p,char op){auto[h,s,e,L,R,d,b]=p;if(op=='O')return {h,s,0,L,2*R,d,2*b};need(op=='Z',"unsupported transfer");return{h+R-e,s,d,L+b,2*R-d,d,2*b};}
I X(P p,int j){return p[0]+p[3]-p[1]+2*j;}
array<I,4> row(P p,int j){return {X(p,j),p[2],p[4]+p[6],p[5]};}
bool strong(G a){int n=a.size(),F=(1<<n)-1;for(int v=0;v<n;v++)a[v]|=1<<v;for(int k=0;k<n;k++)for(int v=0;v<n;v++)if(a[v]>>k&1)a[v]|=a[k];return all_of(a.begin(),a.end(),[&](int x){return x==F;});}
I ipow(I a,int k){I r=1;while(k--)r*=a;return r;}
I f(int n){need(n>=3,"f domain");if(n%3==0)return 3*ipow(5,(n-3)/3);if(n%3==1)return ipow(5,(n-1)/3);return 9*ipow(5,(n-5)/3);}
I g(int n){if(n==0)return 1;need(n>=3,"g domain");if(n==5)return 9;if(n%3==0)return ipow(3,n/3);if(n%3==1)return 5*ipow(3,(n-4)/3);return 25*ipow(3,(n-8)/3);}
int S(I t){int ans=0;for(int n=3;f(n)<=t;n++)ans=n;return ans;}
int Gcap(I t){int ans=0;for(int n=3;g(n)<=t;n++)ans=n;return ans;}
int K(I B,I s){int k=-1;I gg=gcd(B,s);for(I q=1;q<=gg;q++)if(gg%q==0&&S(B/q)>=4)k=max(k,S(B/q)-1+Gcap(q));return k;}
G induced(G a,vector<int>vs){G b(vs.size());for(int i=0;i<(int)vs.size();i++)for(int j=0;j<(int)vs.size();j++)if(a[vs[i]]>>vs[j]&1)b[i]|=1<<j;return b;}
vector<vector<int>> components(G a){int n=a.size();vector<int>reach=a;for(int i=0;i<n;i++)reach[i]|=1<<i;for(int k=0;k<n;k++)for(int i=0;i<n;i++)if(reach[i]>>k&1)reach[i]|=reach[k];int used=0;vector<vector<int>>cs;for(int i=0;i<n;i++)if(!(used>>i&1)){vector<int>v;for(int j=0;j<n;j++)if((reach[i]>>j&1)&&(reach[j]>>i&1)){v.push_back(j);used|=1<<j;}cs.push_back(v);}return cs;}
G edgeext(G a){int n=a.size();a[0]|=1<<n;a.push_back(((1<<n)-1)^1);return a;}
int main(){int all=0,pos=0,equal=0;vector<int>levels;for(int n=1;n<=6;n++){int pc=0;vector<pair<int,int>>es;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)es.push_back({i,j});for(int bits=0;bits<(1<<(int)es.size());bits++){G a(n);for(int k=0;k<(int)es.size();k++){auto[i,j]=es[k];if(bits>>k&1)a[i]|=1<<j;else a[j]|=1<<i;}all++;P p=count(a);I B=X(p,0),s=p[1];need(p[3]>=p[5]&&p[5]>=s&&B>=p[0]&&B>=s,"injection bounds");need(count(edgeext(a))[0]==B,"edge-extension count");if(s==0)continue;pc++;pos++;auto cs=components(a);vector<int>rootcomp,keep;I q=1;for(auto comp:cs){bool root=find(comp.begin(),comp.end(),0)!=comp.end();if(root){rootcomp=comp;keep.insert(keep.end(),comp.begin(),comp.end());}else{for(int u:comp)for(int v=0;v<n;v++)if(v==0)need(a[v]>>u&1,"initial root SCC");if(comp.size()>1){q*=count(induced(a,comp))[0];keep.insert(keep.end(),comp.begin(),comp.end());}}}sort(keep.begin(),keep.end());G red=induced(a,keep);P rp=count(red);need(X(rp,0)==B&&rp[1]==s,"pair-preserving singleton deletion");need(B%q==0&&s%q==0,"tail divisor");need((B==s)==(rootcomp.size()==1),"singleton-root boundary");if(B==s){equal++;need((int)red.size()<=1+Gcap(B),"equal cap");}else{G c=induced(a,rootcomp);G ce=edgeext(c);need(strong(ce),"extended root core strong");need(count(ce)[0]==B/q,"root extension B/q");int cap=K(B,s);need(cap>=0&&(int)red.size()<=cap&&cap<=Gcap(B)-1,"strict cap");need((int)red.size()+1==(int)edgeext(red).size(),"extension size");for(auto v:components(edgeext(red)))need(v.size()>=3,"extended reduced graph components");}}
 levels.push_back(pc);}
 vector<vector<int>>tab;for(int r=1;r<=2;r++){vector<int>a;for(int j=0;j<=8;j++)a.push_back(K(137-2*j,r+3*j));tab.push_back(a);}need(tab==vector<vector<int>>{{9,9,9,9,9,9,9,8,8},{9,10,9,9,9,9,10,8,8}},"base137 cap table");for(int t=1;t<=10000;t++){need(Gcap(t)==0||g(Gcap(t))<=t,"G input");need(g(Gcap(t)==0?3:Gcap(t)+1)>t,"G maximality");for(int s=1;s<=26;s++)if(t>s){int k=K(t,s);if(k>=0)need(k<=Gcap(t)-1,"K versus G");}}
 cout<<"{\n  \"status\": \"PASS\",\n  \"labeled_root_zero_tournaments\": "<<all<<",\n  \"positive_start_inputs\": "<<pos<<",\n  \"B_equals_s_inputs\": "<<equal<<",\n  \"positive_start_counts_by_order_1_to_6\": [";for(int i=0;i<6;i++){if(i)cout<<", ";cout<<levels[i];}cout<<"],\n  \"base137_cap_rows\": [[9,9,9,9,9,9,9,8,8],[9,10,9,9,9,9,10,8,8]],\n  \"cap_arithmetic_targets_checked\": 10000,\n  \"F_8_137\": \"OPEN\"\n}\n";
}
